CREATE DATABASE movie_ticket_booking;

USE movie_ticket_booking;


CREATE TABLE movies (
    movie_id INT PRIMARY KEY AUTO_INCREMENT,
    movie_name VARCHAR(200) NOT NULL,
    language VARCHAR(30),
    genre VARCHAR(50),
    duration_minutes INT,
    release_date DATE,
    certificate VARCHAR(10),
    status VARCHAR(20)
);

