CREATE TABLE seats (
    seat_id INT PRIMARY KEY AUTO_INCREMENT,
    screen_id INT,
    seat_number VARCHAR(10),
    seat_type VARCHAR(20),
    price DECIMAL(10,2),

    FOREIGN KEY (screen_id)
    REFERENCES screens(screen_id)
);

DESC seats;

