 CREATE TABLE shows (
    show_id INT PRIMARY KEY AUTO_INCREMENT,

    movie_id INT,
    screen_id INT,

    show_date DATE,
    start_time TIME,
    end_time TIME,

    language VARCHAR(30),
    show_status VARCHAR(20),

    FOREIGN KEY (movie_id)
    REFERENCES movies(movie_id),

    FOREIGN KEY (screen_id)
    REFERENCES screens(screen_id)
);

