SELECT COUNT(*) FROM bookings;

CREATE TABLE booking_seats (
    booking_seat_id INT PRIMARY KEY AUTO_INCREMENT,

    booking_id INT,
    seat_id INT,

    price DECIMAL(10,2),

    FOREIGN KEY (booking_id)
    REFERENCES bookings(booking_id),

    FOREIGN KEY (seat_id)
    REFERENCES seats(seat_id)
);

