    language,
    COUNT(*) AS total_movies
FROM movies
GROUP BY language
HAVING COUNT(*) > 10;

SELECT
    m.movie_name,
    sh.show_date,
    sh.start_time
FROM movies m
INNER JOIN shows sh
    ON m.movie_id = sh.movie_id;
    
    
SELECT
    m.movie_name,
    t.theatre_name,
    s.screen_name,
    sh.show_date,
    sh.start_time
FROM shows sh

JOIN movies m
    ON sh.movie_id = m.movie_id

JOIN screens s
    ON sh.screen_id = s.screen_id

JOIN theatres t
    ON s.theatre_id = t.theatre_id;
    
    
