    SELECT AVG(price)
    FROM seats
);


UPDATE movies
SET status = 'Running'
WHERE movie_id = 1;

SELECT
    movie_name,
    duration_minutes,

    CASE
        WHEN duration_minutes >= 160 THEN 'Long Movie'
        WHEN duration_minutes >= 120 THEN 'Medium Movie'
        ELSE 'Short Movie'
    END AS movie_category

FROM movies;

SELECT
    movie_name,
    COALESCE(language, 'Unknown') AS movie_language
FROM movies;


SELECT
    m.movie_name,
    SUM(p.amount) AS total_revenue

FROM movies m

JOIN shows sh
    ON m.movie_id = sh.movie_id

JOIN bookings b
    ON sh.show_id = b.show_id

JOIN payments p
    ON b.booking_id = p.booking_id

WHERE p.payment_status = 'Success'

GROUP BY m.movie_id, m.movie_name

ORDER BY total_revenue DESC;


SELECT
    u.user_name,
    m.movie_name,
    sh.show_date,
    sh.start_time,
    b.total_seats,
    b.total_amount,
    b.booking_status

FROM users u

JOIN bookings b
    ON u.user_id = b.user_id

JOIN shows sh
    ON b.show_id = sh.show_id

JOIN movies m
    ON sh.movie_id = m.movie_id

WHERE u.user_id = 1;

SELECT
    payment_status,
    COUNT(*) AS total_transactions,
    SUM(amount) AS total_amount

FROM payments

GROUP BY payment_status;

SELECT
    t.theatre_name,
    SUM(p.amount) AS total_revenue

FROM theatres t

JOIN screens s
    ON t.theatre_id = s.theatre_id

JOIN shows sh
    ON s.screen_id = sh.screen_id

JOIN bookings b
    ON sh.show_id = b.show_id

JOIN payments p
    ON b.booking_id = p.booking_id

WHERE p.payment_status = 'Success'

GROUP BY t.theatre_id, t.theatre_name;


SELECT
    m.movie_name,
    COUNT(b.booking_id) AS total_bookings

FROM movies m

JOIN shows sh
    ON m.movie_id = sh.movie_id

JOIN bookings b
    ON sh.show_id = b.show_id

WHERE b.booking_status = 'Confirmed'

GROUP BY m.movie_id, m.movie_name

ORDER BY total_bookings DESC

LIMIT 5;


SELECT
    s.seat_id,
    s.seat_number,
    s.seat_type,
    s.price

FROM seats s

JOIN shows sh
    ON s.screen_id = sh.screen_id

WHERE sh.show_id = 1

AND s.seat_id NOT IN
(
    SELECT bs.seat_id

    FROM booking_seats bs

    JOIN bookings b
        ON bs.booking_id = b.booking_id

    WHERE b.show_id = 1
    AND b.booking_status = 'Confirmed'
);

CREATE VIEW booking_report AS

SELECT
    b.booking_id,
    u.user_name,
    m.movie_name,
    t.theatre_name,
    s.screen_name,
    b.total_seats,
    b.total_amount,
    b.booking_status

FROM bookings b

JOIN users u
    ON b.user_id = u.user_id

JOIN shows sh
    ON b.show_id = sh.show_id

JOIN movies m
    ON sh.movie_id = m.movie_id

JOIN screens s
    ON sh.screen_id = s.screen_id

JOIN theatres t
    ON s.theatre_id = t.theatre_id;


SELECT * FROM booking_report;


DELIMITER //

CREATE PROCEDURE GetMovieBookings(IN p_movie_id INT)

BEGIN

    SELECT
        m.movie_name,
        COUNT(b.booking_id) AS total_bookings

    FROM movies m

    JOIN shows sh
        ON m.movie_id = sh.movie_id

    JOIN bookings b
        ON sh.show_id = b.show_id

    WHERE m.movie_id = p_movie_id

    GROUP BY m.movie_id, m.movie_name;

END //

DELIMITER ;

CALL GetMovieBookings(1);


DELIMITER //

CREATE TRIGGER check_booking_amount

BEFORE INSERT ON bookings

FOR EACH ROW

BEGIN

    IF NEW.total_amount < 0 THEN

        SIGNAL SQLSTATE '45000'
        SET MESSAGE_TEXT = 'Amount cannot be negative';

    END IF;

END //

DELIMITER ;

START TRANSACTION;

INSERT INTO bookings
(user_id, show_id, total_seats, total_amount, booking_status)

VALUES
(1, 1, 2, 300, 'Confirmed');

INSERT INTO payments
(booking_id, transaction_id, payment_method, amount, payment_status)

VALUES
(LAST_INSERT_ID(), 'TXN999001', 'UPI', 300, 'Success');

COMMIT;

ROLLBACK;

CREATE INDEX idx_movie_name
ON movies(movie_name);

CREATE INDEX idx_booking_user
ON bookings(user_id);

