SELECT
    movie_id,
    movie_name,
    duration_minutes,

    CASE
        WHEN duration_minutes >= 180 THEN 'Very Long'
        WHEN duration_minutes >= 120 THEN 'Long'
        WHEN duration_minutes >= 90 THEN 'Medium'
        ELSE 'Short'
    END AS movie_category

FROM movies;


SELECT
    booking_id,
    total_amount,
    booking_status,

    CASE
        WHEN booking_status = 'Confirmed'
            THEN 'Booking Successful'

        WHEN booking_status = 'Pending'
            THEN 'Waiting for Confirmation'

        WHEN booking_status = 'Cancelled'
            THEN 'Booking Cancelled'

        ELSE 'Unknown'
    END AS booking_message

FROM bookings;


SELECT
    movie_id,
    movie_name,
    COALESCE(language, 'Language Not Available') AS language

FROM movies;


SELECT
    user_id,
    user_name,
    COALESCE(city, 'City Not Available') AS city

FROM users;

SELECT
    sh.show_id,
    m.movie_name,
    t.theatre_name,
    s.screen_name,
    sh.show_date,
    sh.start_time,
    sh.show_status

FROM shows sh

INNER JOIN movies m
    ON sh.movie_id = m.movie_id

INNER JOIN screens s
    ON sh.screen_id = s.screen_id

INNER JOIN theatres t
    ON s.theatre_id = t.theatre_id

ORDER BY sh.show_date, sh.start_time;

SELECT
    b.booking_id,
    u.user_name,
    u.phone,
    m.movie_name,
    t.theatre_name,
    s.screen_name,
    sh.show_date,
    sh.start_time,
    b.total_seats,
    b.total_amount,
    b.booking_status

FROM bookings b

INNER JOIN users u
    ON b.user_id = u.user_id

INNER JOIN shows sh
    ON b.show_id = sh.show_id

INNER JOIN movies m
    ON sh.movie_id = m.movie_id

INNER JOIN screens s
    ON sh.screen_id = s.screen_id

INNER JOIN theatres t
    ON s.theatre_id = t.theatre_id

ORDER BY b.booking_id;


SELECT
    b.booking_id,
    u.user_name,
    m.movie_name,
    p.transaction_id,
    p.payment_method,
    p.amount,
    p.payment_status,
    p.payment_date

FROM payments p

INNER JOIN bookings b
    ON p.booking_id = b.booking_id

INNER JOIN users u
    ON b.user_id = u.user_id

INNER JOIN shows sh
    ON b.show_id = sh.show_id

INNER JOIN movies m
    ON sh.movie_id = m.movie_id

ORDER BY p.payment_date DESC;


SELECT
    seat_id,
    seat_number,
    price

FROM seats

WHERE price >
(
    SELECT AVG(price)
    FROM seats
);

SELECT
    movie_id,
    movie_name,
    duration_minutes

FROM movies

WHERE duration_minutes >
(
    SELECT AVG(duration_minutes)
    FROM movies
);

DROP VIEW IF EXISTS booking_report;

CREATE VIEW booking_report AS

SELECT
    b.booking_id,
    u.user_name,
    u.phone,
    m.movie_name,
    t.theatre_name,
    s.screen_name,
    sh.show_date,
    sh.start_time,
    b.total_seats,
    b.total_amount,
    b.booking_status

FROM bookings b

INNER JOIN users u
    ON b.user_id = u.user_id

INNER JOIN shows sh
    ON b.show_id = sh.show_id

INNER JOIN movies m
    ON sh.movie_id = m.movie_id

INNER JOIN screens s
    ON sh.screen_id = s.screen_id

INNER JOIN theatres t
    ON s.theatre_id = t.theatre_id;
    
SELECT *
FROM booking_report;

SELECT *
FROM booking_report
WHERE booking_status = 'Confirmed';

DROP PROCEDURE IF EXISTS GetMovieBookings;


DELIMITER //

CREATE PROCEDURE GetMovieBookings(IN p_movie_id INT)

BEGIN

    SELECT
        m.movie_name,
        COUNT(b.booking_id) AS total_bookings,
        SUM(b.total_amount) AS total_booking_amount

    FROM movies m

    INNER JOIN shows sh
        ON m.movie_id = sh.movie_id

    INNER JOIN bookings b
        ON sh.show_id = b.show_id

    WHERE m.movie_id = p_movie_id
      AND b.booking_status = 'Confirmed'

    GROUP BY m.movie_id, m.movie_name;

END //

DELIMITER ;

CALL GetMovieBookings(1);

DROP TRIGGER IF EXISTS check_booking_amount;

DELIMITER //

CREATE TRIGGER check_booking_amount

BEFORE INSERT ON bookings

FOR EACH ROW

BEGIN

    IF NEW.total_amount < 0 THEN

        SIGNAL SQLSTATE '45000'
        SET MESSAGE_TEXT = 'Booking amount cannot be negative';

    END IF;

END //

DELIMITER ;

INSERT INTO bookings
(user_id, show_id, total_seats, total_amount, booking_status)

VALUES
(1, 1, 2, -500, 'Confirmed');

START TRANSACTION;

INSERT INTO bookings
(user_id, show_id, total_seats, total_amount, booking_status)

VALUES
(1, 1, 2, 500, 'Confirmed');

SET @new_booking_id = LAST_INSERT_ID();

INSERT INTO payments
(
    booking_id,
    transaction_id,
    payment_method,
    amount,
    payment_status
)

VALUES
(
    @new_booking_id,
    'TXN-DEMO-001',
    'UPI',
    500,
    'Success'
);

COMMIT;

SELECT *
FROM bookings
WHERE booking_id = @new_booking_id;

SELECT *
FROM payments
WHERE booking_id = @new_booking_id;

START TRANSACTION;

UPDATE bookings
SET booking_status = 'Cancelled'
WHERE booking_id = 1;

SELECT booking_id, booking_status
FROM bookings
WHERE booking_id = 1;

ROLLBACK;

SELECT booking_id, booking_status
FROM bookings
WHERE booking_id = 1;



