CREATE INDEX idx_show_date
ON shows(show_date);


SELECT
    SUM(amount) AS total_revenue

FROM payments

WHERE payment_status = 'Success';
-- Successful payments total revenue


SELECT
    payment_status,
    COUNT(*) AS total_transactions,
    SUM(amount) AS total_amount

FROM payments

GROUP BY payment_status;
-- Success / Failed / Pending / Refunded summary


SELECT
    m.movie_name,
    COUNT(b.booking_id) AS total_bookings,
    SUM(p.amount) AS total_revenue

FROM movies m

INNER JOIN shows sh
    ON m.movie_id = sh.movie_id

INNER JOIN bookings b
    ON sh.show_id = b.show_id

INNER JOIN payments p
    ON b.booking_id = p.booking_id

WHERE p.payment_status = 'Success'

GROUP BY m.movie_id, m.movie_name

ORDER BY total_revenue DESC;
-- movie- revenue


SELECT
    t.theatre_name,
    COUNT(b.booking_id) AS total_bookings,
    SUM(p.amount) AS total_revenue

FROM theatres t

INNER JOIN screens s
    ON t.theatre_id = s.theatre_id

INNER JOIN shows sh
    ON s.screen_id = sh.screen_id

INNER JOIN bookings b
    ON sh.show_id = b.show_id

INNER JOIN payments p
    ON b.booking_id = p.booking_id

WHERE p.payment_status = 'Success'

GROUP BY t.theatre_id, t.theatre_name

ORDER BY total_revenue DESC;
-- Theatre-wise revenue

SELECT
    m.movie_name,
    COUNT(b.booking_id) AS total_bookings

FROM movies m

INNER JOIN shows sh
    ON m.movie_id = sh.movie_id

INNER JOIN bookings b
    ON sh.show_id = b.show_id

WHERE b.booking_status = 'Confirmed'

GROUP BY m.movie_id, m.movie_name

ORDER BY total_bookings DESC

LIMIT 5;
--  Top 5 movies

SELECT
    payment_method,
    COUNT(*) AS total_transactions

FROM payments

WHERE payment_status = 'Success'

GROUP BY payment_method

ORDER BY total_transactions DESC;
-- Most Used payment method 


SELECT
    u.user_id,
    u.user_name,
    COUNT(b.booking_id) AS total_bookings,
    SUM(b.total_amount) AS total_spent

FROM users u

LEFT JOIN bookings b
    ON u.user_id = b.user_id

GROUP BY u.user_id, u.user_name

ORDER BY total_spent DESC;
--  user's booking / spending

SELECT
    sh.show_id,
    m.movie_name,
    t.theatre_name,
    s.screen_name,
    sh.show_date,
    sh.start_time,
    sh.show_status

FROM shows sh

JOIN movies m
    ON sh.movie_id = m.movie_id

JOIN screens s
    ON sh.screen_id = s.screen_id

JOIN theatres t
    ON s.theatre_id = t.theatre_id

ORDER BY sh.show_date, sh.start_time;
-- Complete show schedule

SELECT
    b.booking_id,
    u.user_name,
    m.movie_name,
    t.theatre_name,
    b.total_seats,
    b.total_amount

FROM bookings b

JOIN users u
    ON b.user_id = u.user_id

JOIN shows sh
    ON b.show_id = sh.show_id

JOIN movies m
    ON sh.movie_id = m.movie_id

JOIN screens s
    ON sh.screen_id = s.screen_id

JOIN theatres t
    ON s.theatre_id = t.theatre_id

WHERE b.booking_status = 'Confirmed';
-- Confirmed bookings 

SELECT
    s.seat_id,
    s.seat_number,
    s.seat_type,
    s.price

FROM seats s

WHERE s.screen_id =
(
    SELECT screen_id
    FROM shows
    WHERE show_id = 1
)

AND s.seat_id NOT IN
(
    SELECT bs.seat_id

    FROM booking_seats bs

    JOIN bookings b
        ON bs.booking_id = b.booking_id

    WHERE b.show_id = 1
      AND b.booking_status = 'Confirmed'
);
-- Show ID 1-  Not booked  seats

